DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generate_missing_seats` ()   BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE v_id INT;
    DECLARE v_aircraft VARCHAR(50);
    DECLARE cur CURSOR FOR
        SELECT f.id, f.aircraft FROM flights f
         WHERE NOT EXISTS (SELECT 1 FROM flight_seats s WHERE s.flight_id = f.id);
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN cur;
    read_loop: LOOP
        FETCH cur INTO v_id, v_aircraft;
        IF done = 1 THEN LEAVE read_loop; END IF;
        IF v_aircraft LIKE 'Boeing%' THEN
            CALL sp_generate_seats(v_id, 3, 14);
        ELSE
            CALL sp_generate_seats(v_id, 2, 10);
        END IF;
    END LOOP;
    CLOSE cur;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generate_seats` (IN `p_flight_id` INT, IN `p_business_rows` INT, IN `p_economy_rows` INT)   BEGIN
    DECLARE r INT DEFAULT 1;
    DECLARE c INT;
    DECLARE total_rows INT;
    SET total_rows = p_business_rows + p_economy_rows;

    WHILE r <= total_rows DO
        SET c = 0;
        WHILE c < 6 DO
            INSERT INTO flight_seats (flight_id, seat_code, seat_class)
            VALUES (
                p_flight_id,
                CONCAT(LPAD(r, 2, '0'), CHAR(65 + c)),
                IF(r <= p_business_rows, 'BUSINESS', 'ECONOMY')
            );
            SET c = c + 1;
        END WHILE;
        SET r = r + 1;
    END WHILE;

    UPDATE flights
       SET seats_business_left = p_business_rows * 6,
           seats_economy_left  = p_economy_rows * 6
     WHERE id = p_flight_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_member_tier` (IN `p_user_id` INT)   BEGIN
    DECLARE v_points INT;
    DECLARE v_new_tier VARCHAR(10);

    SELECT points INTO v_points FROM users WHERE id = p_user_id;

    SET v_new_tier = CASE
        WHEN v_points >= 6000 THEN 'BachKim'
        WHEN v_points >= 3000 THEN 'Vang'
        WHEN v_points >= 1000 THEN 'Bac'
        ELSE 'PhoThong'
    END;

    -- tier_updated_at phải đứng trước tier để so sánh với hạng cũ
    UPDATE users
       SET tier_updated_at = IF(tier <> v_new_tier, NOW(), tier_updated_at),
           tier = v_new_tier
     WHERE id = p_user_id AND role = 'Khach_Hang';
END$$

DELIMITER ;

