--
-- Table structure for table `passengers`
--

CREATE TABLE `passengers` (
  `id` int(11) NOT NULL,
  `booking_id` int(11) NOT NULL,
  `passenger_type` enum('adult','child','infant') DEFAULT 'adult',
  `title` enum('MR','MRS','MS','MSTR','MISS') NOT NULL,
  `first_name` varchar(50) NOT NULL,
  `last_name` varchar(50) NOT NULL,
  `dob` date NOT NULL,
  `id_number` varchar(50) DEFAULT NULL,
  `nationality` varchar(50) DEFAULT 'Vietnam',
  `seat_class` enum('ECONOMY','BUSINESS') NOT NULL DEFAULT 'ECONOMY',
  `flight_seat_id` int(11) DEFAULT NULL,
  `seat_price` decimal(12,0) DEFAULT 0,
  `baggage_weight` int(11) DEFAULT 0,
  `baggage_price` decimal(12,0) DEFAULT 0,
  `meal_name` varchar(100) DEFAULT NULL,
  `meal_price` decimal(12,0) DEFAULT 0,
  `insurance_price` decimal(12,0) DEFAULT 0,
  `checkin_status` tinyint(1) DEFAULT 0,
  `boarding_pass_code` varchar(50) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `passengers`
